// Last-variable IBP on a known J reduction/connection. No momentum IBP input.
#define main j_search_unused_entry
#include "search.cpp"
#undef main
#include <filesystem>
#include <chrono>
Rat rc(U c){return Rat(std::vector<U>{c});}
Rat plus(const Rat&a,const Rat&b){return a-(rc(prime-1)*b);}
Rat deriv(const Rat&a){Rat x;Poly n1,d1,tmp;nmod_poly_derivative(n1.v,a.n.v);nmod_poly_derivative(d1.v,a.d.v);nmod_poly_mul(x.n.v,n1.v,a.d.v);nmod_poly_mul(tmp.v,a.n.v,d1.v);nmod_poly_sub(x.n.v,x.n.v,tmp.v);nmod_poly_mul(x.d.v,a.d.v,a.d.v);x.normal();return x;}
U scalar(std::string a){auto slash=a.find('/');long long n=std::stoll(a.substr(0,slash)),d=slash==std::string::npos?1:std::stoll(a.substr(slash+1));auto norm=[](long long x){return U((x%static_cast<long long>(prime)+prime)%prime);};return nmod_div(norm(n),norm(d),mod);}
Rat getrat(const json&v){Rat a(v.at("numerator_tau").get<std::vector<U>>());Rat b(v.at("denominator_tau").get<std::vector<U>>());return a/b;}
U evaluate(const Rat&a,U point){U n=nmod_poly_evaluate_nmod(a.n.v,point),d=nmod_poly_evaluate_nmod(a.d.v,point);if(!d)throw std::runtime_error("singular certificate endpoint requires separate limit");return nmod_div(n,d,mod);}
Poly lcm(const Poly&a,const Poly&b){Poly g,q,c;nmod_poly_gcd(g.v,a.v,b.v);nmod_poly_div(q.v,a.v,g.v);nmod_poly_mul(c.v,q.v,b.v);return c;}
Poly clear(const Rat&a,const Poly&D){Poly q,r,out;nmod_poly_divrem(q.v,r.v,D.v,a.d.v);if(!r.zero())throw std::runtime_error("failed to clear denominator");nmod_poly_mul(out.v,q.v,a.n.v);return out;}
using RVec=std::vector<Rat>;
RVec covariant(const RVec&g,const std::vector<RVec>&A){int r=g.size();RVec v(r);for(int j=0;j<r;++j){v[j]=deriv(g[j]);for(int i=0;i<r;++i)v[j]=plus(v[j],g[i]*A[i][j]);}return v;}
#ifndef J_FI_IBP_LIBRARY_ONLY
int main(int argc,char**argv){try{
 if(argc<3||argc>5)throw std::runtime_error("usage: fi_ibp CONFIG OUTPUT [J_REDUCTION_OVERRIDE [MASTERS_INFO_OVERRIDE]]");
 json cfg,data;{std::ifstream f(argv[1]);f>>cfg;}auto base=std::filesystem::path(argv[1]).parent_path();auto source=argc>=4?std::filesystem::path(argv[3]):base/cfg.at("j_reduction").get<std::string>();{std::ifstream f(source);f>>data;}
 if(!cfg.contains("endpoint_values")||!cfg.contains("integration_bounds_tau"))throw std::runtime_error("explicit integration endpoints and endpoint-value maps are required");
 prime=data.at("prime");nmod_init(&mod,prime);int degree=cfg.value("degree",8);auto names=data.at("masters").get<std::vector<std::string>>();int r=names.size();std::map<std::string,int>idx;for(int i=0;i<r;++i)idx[names[i]]=i;
 std::vector<RVec>A(r,RVec(r));for(int i=0;i<r;++i){auto&de=data.at("de").at(names[i]);if(!de.contains("rhs"))throw std::runtime_error("J DE not closed");for(auto it=de["rhs"].begin();it!=de["rhs"].end();++it)A[i][idx.at(it.key())]=getrat(it.value());}
 const auto full_names=names;const auto full_idx=idx;const auto full_A=A;const int full_rank=r;
 std::set<std::string>discarded;if(cfg.contains("discarded_modules"))for(auto&v:cfg.at("discarded_modules"))discarded.insert(v.get<std::string>());
 if(!discarded.empty()){std::vector<int>keep;for(int i=0;i<r;++i)if(!discarded.count(names[i]))keep.push_back(i);for(int i=0;i<r;++i)if(discarded.count(names[i]))for(int j:keep)if(!A[i][j].zero())throw std::runtime_error("discarded functions are not a differential submodule");std::vector<RVec>projected(keep.size(),RVec(keep.size()));std::vector<std::string>new_names;for(int i=0;i<int(keep.size());++i){new_names.push_back(names[keep[i]]);for(int j=0;j<int(keep.size());++j)projected[i][j]=A[keep[i]][keep[j]];}A=std::move(projected);names=std::move(new_names);r=names.size();idx.clear();for(int i=0;i<r;++i)idx[names[i]]=i;}
 auto full_row=[&](const std::string&label){RVec v(full_rank);if(data.at("reductions").contains(label)){auto row=data.at("reductions").at(label);for(auto it=row.begin();it!=row.end();++it)v[full_idx.at(it.key())]=getrat(it.value());}else v[full_idx.at(label)]=rc(1);return v;};
 Rat den=rc(1);
 if(cfg.at("certificate_denominator").is_string()){
  Poly common;nmod_poly_one(common.v);for(auto&row:A)for(auto&v:row)common=lcm(common,v.d);
  if(cfg.at("certificate_denominator")=="all_lcm")for(auto it=data.at("reductions").begin();it!=data.at("reductions").end();++it)for(auto jt=it.value().begin();jt!=it.value().end();++jt)common=lcm(common,getrat(jt.value()).d);
  den=Rat(coeffs(common));
 }else{auto&selection=cfg.at("certificate_denominator");auto entry=data["de"][selection.at("matrix_row").get<std::string>()]["rhs"][selection.at("matrix_column").get<std::string>()];den=Rat(entry.at("denominator_tau").get<std::vector<U>>());}
 Rat original_den=den;for(int k=1;k<cfg.value("denominator_power",1);++k)den=den*original_den;
 std::cerr<<"FI certificate denominator degree="<<nmod_poly_degree(den.n.v)<<" numerator limit="<<degree<<" J rank="<<r<<"\n";
 std::map<std::string,RVec>targets;for(int i=0;i<r;++i)if(names[i][0]=='J'){RVec row(r);row[i]=rc(1);targets[names[i]]=row;}
 for(auto it=data.at("reductions").begin();it!=data.at("reductions").end();++it)if(it.key()[0]=='J'){RVec row(r);for(auto jt=it.value().begin();jt!=it.value().end();++jt)if(!discarded.count(jt.key()))row[idx.at(jt.key())]=getrat(jt.value());targets[it.key()]=row;}
 std::vector<std::string>constant_names;if(cfg.contains("master_integrands_from")){json info;auto infoSource=argc==5?std::filesystem::path(argv[4]):base/cfg.at("master_integrands_from").get<std::string>();std::ifstream f(infoSource);f>>info;for(auto&nu:info.at("master_indices")){std::string label="J{";for(size_t i=0;i<nu.size();++i){if(nu[i].get<int>()<1)throw std::runtime_error("FI comparison basis must be dot-only");label+=(i?",":"")+nu[i].dump();}constant_names.push_back(label+"}");}}
 else if(cfg.contains("master_integrands")&&cfg.at("master_integrands").is_string()){for(auto&[name,row]:targets)constant_names.push_back(name);std::sort(constant_names.begin(),constant_names.end(),[](const auto&a,const auto&b){int ca=complexity(a),cb=complexity(b);return ca!=cb?ca<cb:a<b;});}else constant_names=cfg.contains("master_integrands")?cfg.at("master_integrands").get<std::vector<std::string>>():names;
 int constants=constant_names.size();std::map<std::string,int>constant_idx;std::vector<RVec>columns;
 for(int i=0;i<constants;++i){const auto&name=constant_names[i];constant_idx[name]=i;if(targets.count(name))columns.push_back(targets.at(name));else{RVec e(r);e[idx.at(name)]=rc(1);columns.push_back(e);}}
 std::vector<RVec>generators;for(int i=0;i<r;++i){Rat factor=rc(1);if(cfg.at("endpoint_zeros").contains(names[i]))for(auto&v:cfg["endpoint_zeros"][names[i]]){U a=scalar(v.get<std::string>());factor=factor*Rat(std::vector<U>{a?prime-a:0,1});}for(int k=0;k<=degree;++k){std::vector<U>power(k+1);power[k]=1;RVec g(r);g[i]=factor*Rat(power)/den;columns.push_back(covariant(g,A));generators.push_back(std::move(g));}}
 std::vector<std::string>labels;for(auto&[label,v]:targets)labels.push_back(label);int unknowns=columns.size(),T=labels.size();
 std::vector<int>column_order;if(cfg.value("prefer_derivatives",false)){for(int i=constants;i<unknowns;++i)column_order.push_back(i);for(int i=0;i<constants;++i)column_order.push_back(i);}else for(int i=0;i<unknowns;++i)column_order.push_back(i);
 std::vector<Poly>D(r);for(int j=0;j<r;++j){nmod_poly_one(D[j].v);for(auto&col:columns)D[j]=lcm(D[j],col[j].d);for(auto&[l,row]:targets)D[j]=lcm(D[j],row[j].d);}
 std::vector<std::vector<U>>matrix;for(int j=0;j<r;++j){std::vector<Poly>polys;int maxdeg=0;for(int col:column_order){polys.push_back(clear(columns[col][j],D[j]));maxdeg=std::max(maxdeg,int(nmod_poly_degree(polys.back().v)));}for(auto&label:labels){polys.push_back(clear(targets.at(label)[j],D[j]));maxdeg=std::max(maxdeg,int(nmod_poly_degree(polys.back().v)));}for(int k=0;k<=maxdeg;++k){std::vector<U>row;for(auto&p:polys)row.push_back(nmod_poly_get_coeff_ui(p.v,k));matrix.push_back(std::move(row));}}
 int pivotrow=0;std::vector<int>pc;for(int col=0;col<unknowns&&pivotrow<int(matrix.size());++col){int k=pivotrow;while(k<int(matrix.size())&&!matrix[k][col])++k;if(k==int(matrix.size()))continue;std::swap(matrix[k],matrix[pivotrow]);U inv=nmod_inv(matrix[pivotrow][col],mod);for(U&v:matrix[pivotrow])v=mul(v,inv);for(int i=0;i<int(matrix.size());++i)if(i!=pivotrow&&matrix[i][col]){U c=matrix[i][col];for(int j=col;j<unknowns+T;++j)matrix[i][j]=sub(matrix[i][j],mul(c,matrix[pivotrow][j]));}pc.push_back(col);++pivotrow;}
 json output={{"prime",prime},{"j_masters",names},{"discarded_modules",discarded},{"master_integrands",constant_names},{"certificate_degree",degree},{"reductions",json::object()},{"certificate_checks",0},{"failures",json::array()},{"method","r_target = sum c_a r_master_a + g_prime + g A + explicit discarded-module remainder; c_a independent of integration variable"}};
 output["selected_master_integrands"]=json::array();for(int col:pc)if(column_order[col]<constants)output["selected_master_integrands"].push_back(constant_names[column_order[col]]);output["selected_master_count"]=output["selected_master_integrands"].size();std::cerr<<"FI selected candidate masters="<<output["selected_master_count"]<<"\n";
 int checks=0;for(int a=0;a<T;++a){bool ok=true;for(int i=pivotrow;i<int(matrix.size());++i)if(matrix[i][unknowns+a])ok=false;if(!ok){output["failures"].push_back(labels[a]);continue;}std::vector<U>solution(unknowns);for(int i=0;i<pivotrow;++i)solution[column_order[pc[i]]]=matrix[i][unknowns+a];RVec g(r);for(int k=0;k<int(generators.size());++k)if(solution[constants+k])for(int j=0;j<r;++j)g[j]=plus(g[j],rc(solution[constants+k])*generators[k][j]);auto dc=covariant(g,A);for(int j=0;j<r;++j){Rat difference=targets.at(labels[a])[j]-dc[j];for(int k=0;k<constants;++k)difference=difference-rc(solution[k])*columns[k][j];if(!difference.zero())throw std::runtime_error("exact FI IBP certificate failed");}++checks;
  std::vector<U>integrated(solution.begin(),solution.begin()+constants),boundary(constants);
  for(int j=0;j<r;++j)for(int end=0;end<2;++end){auto map=cfg.at("endpoint_values").at(names[j]).at(end?"upper":"lower");if(map.empty())continue;U v=evaluate(g[j],scalar(cfg.at("integration_bounds_tau")[end].get<std::string>()));if(!end&&v)v=prime-v;for(auto it=map.begin();it!=map.end();++it){int k=constant_idx.at(it.key());boundary[k]=add(boundary[k],mul(v,scalar(it.value().get<std::string>())));}}
  for(int j=0;j<constants;++j)integrated[j]=add(integrated[j],boundary[j]);
  json coeff=json::object(),certificate=json::object(),physical=json::object(),boundary_coeff=json::object();for(int j=0;j<r;++j)certificate[names[j]]=ratjson(g[j]);for(int j=0;j<constants;++j){coeff[constant_names[j]]=integrated[j];boundary_coeff[constant_names[j]]=boundary[j];json map=cfg.value("identity_fi_map",false)?json{{"FI"+constant_names[j].substr(1),"1"}}:cfg.at("period_integral_map").at(constant_names[j]);for(auto it=map.begin();it!=map.end();++it){U v=mul(integrated[j],scalar(it.value().get<std::string>()));physical[it.key()]=add(physical.value(it.key(),U(0)),v);}}
  json remainder=json::object();if(!discarded.empty()){RVec extended_g(full_rank);for(int j=0;j<r;++j)extended_g[full_idx.at(names[j])]=g[j];auto derivative=covariant(extended_g,full_A);auto difference=full_row(labels[a]);for(int j=0;j<full_rank;++j)difference[j]=difference[j]-derivative[j];for(int k=0;k<constants;++k){auto row=full_row(constant_names[k]);for(int j=0;j<full_rank;++j)difference[j]=difference[j]-rc(solution[k])*row[j];}for(int j=0;j<full_rank;++j){if(discarded.count(full_names[j]))remainder[full_names[j]]=ratjson(difference[j]);else if(!difference[j].zero())throw std::runtime_error("unprojected FI certificate has a non-boundary remainder");}}
  output["reductions"][labels[a]]={{"period_coefficients",coeff},{"boundary_contribution",boundary_coeff},{"fi_coefficients",physical},{"certificate",certificate},{"discarded_module_remainder",remainder}};
 }
 output["certificate_checks"]=checks;output["all_targets_reduced"]=output["failures"].empty();{std::ofstream f(argv[2]);if(!f)throw std::runtime_error("cannot open FI output");f<<output.dump(2);}std::cout<<"FI IBP exact certificates="<<checks<<"; failures="<<output["failures"].size()<<"\n";return output["failures"].empty()?0:2;
 }catch(const std::exception&e){std::cerr<<"fi_ibp: "<<e.what()<<"\n";return 1;}}
#endif
